function iiDN(k){return (T_DN[LANG_DN]||T_DN.fr)[k]||(T_DN.fr)[k]||k;}
function applyLangDN(){
  document.documentElement.lang=LANG_DN;
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    var v=iiDN(el.dataset.i18n);if(v)el.innerHTML=v;
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(function(el){
    var v=iiDN(el.dataset.i18nPh);if(v)el.placeholder=v;
  });
  document.querySelectorAll('.lbtn').forEach(function(b){
    b.classList.toggle('on',b.dataset.lang===LANG_DN);
  });
  var sp=document.getElementById('xsearch');
  if(sp) sp.placeholder=iiDN('ds.ph');
  if(typeof xRender==='function') xRender();
}
function setLangDN(lang){
  LANG_DN=lang;
  var u=new URL(window.location.href);
  u.searchParams.set('lang',lang);
  history.replaceState({},'',u);
  applyLangDN();
}

if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",applyLangDN);}else{applyLangDN();}


